contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string memory name_, string memory tokenURI, bool finiteSupply, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance, uint256 quantity) public {
        require(bytes(tokenURI).length > 0);
        require(quantity > 0 && quantity <= itemsRemaining);
        uint256 before = c.uniqueTokensOutstanding();
        c.createGameItem(name_, tokenURI, finiteSupply, false, itemsRemaining, itemPrice, dailyAllowance);
        uint256 tokenId = before;
        bool reverted;
        try c.adjustTransferability(tokenId, true) { reverted = false; } catch { reverted = true; }
        assert(
            reverted &&
            c.uniqueTokensOutstanding() == before + 1 &&
            keccak256(bytes(c.uri(tokenId))) == keccak256(bytes(tokenURI)) &&
            c.remainingSupply(tokenId) == itemsRemaining
        );
    }
    receive() external payable {}
}

